/**
 * Toolbar group for opening existing kits from folder, file, or remote URL.
 **/
const HomeToolbarOpen: FC = () => {
  const availableKitKinds = useAvailableKitKinds();
  const kits = useKits();
  const defaultKitName = useLabel("compose.sketchpad.app.kit.defaultName");
  const { createKit, navigateToKit, storeKitFileBlobs } = useSketchpadCommands();
  const actor = useSketchpadActor();

  const handleOpenFolder = useCallback(async () => {
    const existingNames = kits.map((kit) => kit.name);
    const uniqueName = generateUniqueName(defaultKitName ?? "", existingNames) ?? defaultKitName ?? "";
    const newKit: Kit = { guid: guid(), name: uniqueName, version: "", types: [], designs: [] };
    try {
      await createKit("compose.sketchpad.app.home.toolbar.openFolder", newKit, true, false);
      navigateToKit(newKit.guid);
    } catch (error) {
      console.error("[Home] Failed to open folder kit:", error);
    }
  }, [createKit, defaultKitName, kits, navigateToKit]);

  const handleOpenFile = useCallback(() => {
    const fileInput = document.getElementById("compose.sketchpad.app.home.importKit") as HTMLInputElement | null;
    if (fileInput) {
      fileInput.click();
    }
  }, []);

  const handleOpenRemote = useCallback(async () => {
    const url = prompt("Enter compose sketchpad URL:");
    if (!url) return;
    const operationId = `kit-import-${guid()}`;
    actor.send({ type: "BACKGROUND.START", operationId, operationType: `kit-import:remote` });
    try {
      const { kit } = await importKit(url);
      await createKit("compose.sketchpad.app.home.toolbar.openRemote", kit, false, false);
      await storeKitFileBlobs(kit.guid, kit);
      actor.send({ type: "BACKGROUND.COMPLETE", operationId });
      navigateToKit(kit.guid);
    } catch (error) {
      console.error("[Home] Failed to import remote kit:", error);
      actor.send({ type: "BACKGROUND.FAIL", operationId, error: error instanceof Error ? error.message : String(error) });
    }
  }, [actor, createKit, navigateToKit, storeKitFileBlobs]);

  const labelFolder = useLabel("compose.sketchpad.app.home.toolbar.openFolder");
  const labelFile = useLabel("compose.sketchpad.app.home.toolbar.openFile");
  const labelRemote = useLabel("compose.sketchpad.app.home.toolbar.openRemote");

  return (
    <ToolbarGroup>
      {availableKitKinds.local && <Action id="compose.sketchpad.app.home.toolbar.openFolder" icon={<FolderIcon />} text={labelFolder ?? "Folder"} onClick={handleOpenFolder} />}
      <Action id="compose.sketchpad.app.home.toolbar.openFile" icon={<DocumentIcon />} text={labelFile ?? "File"} onClick={handleOpenFile} />
      {availableKitKinds.remote && <Action id="compose.sketchpad.app.home.toolbar.openRemote" icon={<RemoteKitIcon />} text={labelRemote ?? "Remote"} onClick={handleOpenRemote} />}
    </ToolbarGroup>
  );
};

